fn solve(word: Vec<char>) -> Vec<char> {
    // Define sets as arrays of chars
    const SET_A: &[char] = &['A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N', 'T', 'V', 'W', 'X', 'Y', 'Z'];
    const SET_B: &[char] = &['B', 'C', 'D', 'G', 'J', 'O', 'P', 'Q', 'R', 'S', 'U'];

    // Helper closure to check membership in a set
    let is_in_set_a = |c: char| SET_A.contains(&c);
    let is_in_set_b = |c: char| SET_B.contains(&c);

    // Determine the set of the first character
    if word.is_empty() {
        // According to problem constraints, input length is at least 1,
        // but handle empty input gracefully by returning "NO"
        return "NO".chars().collect();
    }

    let first_char = word[0];
    let in_a = is_in_set_a(first_char);
    let in_b = is_in_set_b(first_char);

    // If first char is not in any set, return NO immediately.
    if !in_a && !in_b {
        return "NO".chars().collect();
    }

    // Check if all characters belong to the same set as the first char
    let all_same_set = word.iter().all(|&c| {
        if in_a {
            is_in_set_a(c)
        } else {
            is_in_set_b(c)
        }
    });

    if all_same_set {
        "YES".chars().collect()
    } else {
        "NO".chars().collect()
    }
}